<template><div><div class="page-head"><div><h1>Administrative overview</h1><p>Live recommendation, assessment, and admissions information.</p></div><span class="updated">Updated {{ updated }}</span></div><div v-if="loading" class="loading">Loading dashboard…</div><template v-else><section class="stats"><article v-for="card in cards" :key="card.label" class="stat"><small>{{ card.label }}</small><strong>{{ card.value }}</strong><span>{{ card.note }}</span></article></section><section class="panel recommendation-overview"><div class="panel-title"><div><small>CAREER RECOMMENDATIONS</small><h2>Program guidance overview</h2></div></div><div class="guidance-metrics"><p><strong>{{ data.recommendation_summary?.generated_students || 0 }}</strong> students with generated matches on their latest attempt</p><p><strong>{{ data.recommendation_summary?.ai_generated_students || 0 }}</strong> with AI explanations generated</p></div><p class="guidance-note">Highest matches from saved guidance on each student's latest attempt. Ties count toward each matched program; these are not enrollment choices.</p><div class="table-wrap"><table><thead><tr><th>Highest-matching program</th><th>Students</th></tr></thead><tbody><tr v-for="program in data.recommendation_summary?.top_programs" :key="program.code"><td>{{ program.code }}</td><td>{{ program.students }}</td></tr><tr v-if="!data.recommendation_summary?.top_programs?.length"><td colspan="2" class="empty">No generated matches yet.</td></tr></tbody></table></div></section><section class="panel"><div class="panel-title"><div><small>RECENT ACTIVITY</small><h2>Latest exam submissions</h2></div><router-link to="/results">View all results →</router-link></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Applicant number</th><th>Score</th><th>Status</th><th>Date</th></tr></thead><tbody><tr v-for="result in data.latest_results" :key="result.id"><td><strong>{{ result.student?.first_name }} {{ result.student?.last_name }}</strong></td><td>{{ result.student?.student_number }}</td><td>{{ result.total_score }}/100</td><td><span :class="['status',result.official_outcome==='PASSED'?'':'failed']">{{ result.official_outcome }}</span></td><td>{{ formatDate(result.exam_date) }}</td></tr><tr v-if="!data.latest_results?.length"><td colspan="5" class="empty">No exam submissions yet.</td></tr></tbody></table></div></section></template></div></template>
<script setup>import{computed,onMounted,ref}from'vue';import api from'../utils/api';const loading=ref(true),data=ref({stats:{},latest_results:[]}),updated=ref('');const cards=computed(()=>[{label:'Registered students',value:data.value.stats.students||0,note:`${data.value.stats.active_students||0} active accounts`},{label:'Exam submissions',value:data.value.stats.exam_submissions||0,note:`${data.value.stats.passed||0} students officially passed`},{label:'Applicants with submissions',value:data.value.stats.exam_students||0,note:'Unique students, excluding repeat attempts'},{label:'Awaiting review',value:data.value.stats.pending_results||0,note:'Pending exam results'},{label:'Academic programs',value:data.value.stats.programs||0,note:`${data.value.stats.questions||0} exam questions`}]);const formatDate=d=>d?new Date(d).toLocaleDateString():'—';onMounted(async()=>{try{data.value=(await api.get('/admin/dashboard')).data;updated.value=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}finally{loading.value=false}})</script>
<style scoped>.recommendation-overview{margin-bottom:24px}.guidance-metrics{display:flex;flex-wrap:wrap;gap:24px;padding:0 20px;font-size:13px}.guidance-metrics strong{font-size:24px;color:#14532d}.guidance-note{padding:0 20px 16px;font-size:12px;color:#647168;line-height:1.6}.stat span{font-size:11px;color:#738078}.updated{font-size:10px;color:#77837b;text-transform:uppercase}.panel-title{padding:20px;display:flex;justify-content:space-between;align-items:center}.panel-title small{font-size:8px;letter-spacing:.14em;color:#a27e0a}.panel-title h2{font:23px Georgia;margin:5px 0;color:#163f29}.panel-title a{font-size:11px;font-weight:800;color:#14603a}</style>
